.nifty-part-header-2 .bt-header .bt-brief-tab {position:fixed;right:0;top:50%;z-index:8;display:flex;flex-direction:column;align-items:center;gap:14px;width:46px;padding:16px 0 18px;margin-top:-104px;background:linear-gradient(180deg,#004877 0%,#002a47 100%);color:#fff;cursor:pointer;border-radius:8px 0 0 8px;box-shadow:-12px 16px 36px -16px rgba(0,29,51,.7);transition:width .5s var(--ease),box-shadow .5s var(--ease);overflow:hidden}
