.bt-home .bt-hero-visual{position:relative;min-width:0;width:100%;max-width:430px;margin-left:auto;padding:26px 28px 28px;background:rgba(18,19,20,.5);-webkit-backdrop-filter:blur(18px) saturate(1.15);backdrop-filter:blur(18px) saturate(1.15);border:1px solid rgba(255,255,255,.2)}
