/* 6. visualiser teaser: one room, interchangeable tiles */
.bt-home .bt-viz{display:grid;grid-template-columns:minmax(0,.74fr) minmax(0,1.26fr);gap:clamp(32px,5.5vw,96px);align-items:center}
.bt-home .bt-viz .bt-h2{margin-bottom:26px}
.bt-home .bt-viz-list{margin:30px 0 38px;border-top:1px solid var(--line)}
.bt-home .bt-viz-list li{display:flex;gap:18px;padding:15px 0;border-bottom:1px solid var(--line);font-size:16px;color:var(--body)}
.bt-home .bt-viz-list b{flex:0 0 96px;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--navy);padding-top:6px}
.bt-home .bt-viz-visual{position:relative;min-width:0;perspective:1800px}
.bt-home .bt-rt{position:absolute;left:50%;top:40%;width:1px;height:1px;opacity:0;pointer-events:none;margin:0}
.bt-home .bt-room{position:relative;aspect-ratio:1280/714;overflow:hidden;background:#cfc8bc;transform:rotateY(-9deg) rotateX(2deg);transform-origin:100% 50%;transition:transform 1.2s var(--ease);box-shadow:-40px 50px 70px -44px rgba(29,30,31,.6)}
.bt-home .bt-viz-visual:hover .bt-room{transform:rotateY(0deg) rotateX(0deg)}
.bt-home .bt-room img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity 1s var(--ease)}
.bt-home .bt-room-tag{position:absolute;left:0;top:0;z-index:2;display:none;background:rgba(17,18,19,.78);color:#fff;padding:12px 18px;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase}
.bt-home .bt-rt1:checked~.bt-room .bt-rf1,.bt-home .bt-rt2:checked~.bt-room .bt-rf2,.bt-home .bt-rt3:checked~.bt-room .bt-rf3,.bt-home .bt-rt4:checked~.bt-room .bt-rf4{opacity:1}
.bt-home .bt-rt1:checked~.bt-room .bt-rg1,.bt-home .bt-rt2:checked~.bt-room .bt-rg2,.bt-home .bt-rt3:checked~.bt-room .bt-rg3,.bt-home .bt-rt4:checked~.bt-room .bt-rg4{display:block}
.bt-home .bt-room-opts{position:relative;z-index:2;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:-34px 0 0 clamp(16px,4vw,64px);background:#fff;box-shadow:0 30px 44px -30px rgba(29,30,31,.45)}
.bt-home .bt-ro{display:flex;align-items:center;gap:12px;padding:14px 16px;cursor:pointer;border-left:1px solid var(--line);transition:background .5s var(--ease),color .5s var(--ease);min-width:0}
.bt-home .bt-ro:first-child{border-left:0}
.bt-home .bt-ro img{width:44px;height:44px;object-fit:cover;flex-shrink:0}
.bt-home .bt-ro b{display:block;font-family:var(--serif);font-weight:500;font-size:clamp(15px,1.25vw,19px);line-height:1.15}
.bt-home .bt-ro small{display:block;font-size:10.5px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;color:var(--mut);margin-top:4px}
.bt-home .bt-ro:hover{background:var(--sand)}
.bt-home .bt-rt1:checked~.bt-room-opts .bt-ro1,.bt-home .bt-rt2:checked~.bt-room-opts .bt-ro2,.bt-home .bt-rt3:checked~.bt-room-opts .bt-ro3,.bt-home .bt-rt4:checked~.bt-room-opts .bt-ro4{background:var(--navy);color:#fff}
.bt-home .bt-rt1:checked~.bt-room-opts .bt-ro1 small,.bt-home .bt-rt2:checked~.bt-room-opts .bt-ro2 small,.bt-home .bt-rt3:checked~.bt-room-opts .bt-ro3 small,.bt-home .bt-rt4:checked~.bt-room-opts .bt-ro4 small{color:rgba(255,255,255,.7)}
.bt-home .bt-rt1:focus-visible~.bt-room-opts .bt-ro1,.bt-home .bt-rt2:focus-visible~.bt-room-opts .bt-ro2,.bt-home .bt-rt3:focus-visible~.bt-room-opts .bt-ro3,.bt-home .bt-rt4:focus-visible~.bt-room-opts .bt-ro4{outline:2px solid var(--sky);outline-offset:-2px}

/* 7. complete the room */

/* 8. story */
.bt-home .bt-story{display:grid;grid-template-columns:minmax(0,.82fr) minmax(0,1.18fr);gap:clamp(40px,7vw,120px);align-items:center}
.bt-home .bt-story-fig{position:relative;margin:0;margin-right:clamp(16px,3vw,44px);perspective:1600px}
.bt-home .bt-story-fig img{width:100%;aspect-ratio:4/5;object-fit:cover;box-shadow:34px 44px 60px -40px rgba(29,30,31,.5)}
.bt-home .bt-story-badge{position:absolute;right:calc(clamp(16px,3vw,44px) * -1);bottom:clamp(20px,3vw,44px);background:var(--navy);color:#fff;padding:26px 30px 24px;box-shadow:20px 30px 40px -24px rgba(0,40,70,.55)}
.bt-home .bt-story-badge b{display:block;font-family:var(--serif);font-weight:500;font-size:clamp(64px,7vw,104px);line-height:.85;letter-spacing:-.02em}
.bt-home .bt-story-badge b sup{font-size:.45em;vertical-align:top;line-height:1.4}
.bt-home .bt-story-badge span{display:block;margin-top:16px;font-size:11px;line-height:1.55;font-weight:500;letter-spacing:.2em;text-transform:uppercase;max-width:17ch}
.bt-home .bt-story .bt-h2{margin-bottom:26px}
.bt-home .bt-story p+p{margin-top:16px}
.bt-home .bt-story .bt-link{margin-top:34px}

/* 9. showroom */
.bt-home .bt-show{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(32px,6vw,96px);align-items:stretch}
.bt-home .bt-show .bt-h2{margin-bottom:22px}
.bt-home .bt-show-nap{font-family:var(--serif);font-weight:500;font-style:normal;font-size:clamp(23px,2vw,29px);line-height:1.3;margin:30px 0 6px}
.bt-home .bt-show-tel{display:inline-block;font-family:var(--serif);font-weight:500;font-size:clamp(23px,2vw,29px);line-height:1.3;color:var(--navy);border-bottom:1px solid var(--line);transition:border-color .4s var(--ease)}
.bt-home .bt-show-tel:hover{border-color:var(--navy)}
.bt-home .bt-hours{margin:30px 0 36px;max-width:440px;font-size:16.5px}
.bt-home .bt-hours div{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid var(--line)}
.bt-home .bt-hours div:first-child{border-top:1px solid var(--line)}
.bt-home .bt-hours dt{margin:0;color:var(--body)}
.bt-home .bt-hours dd{margin:0;font-weight:500;color:var(--ink);white-space:nowrap}
.bt-home .bt-map{position:relative;min-height:460px;background:var(--sand);border:1px solid var(--line)}
.bt-home .bt-map iframe{position:absolute;inset:0;width:100%;height:100%;border:0;filter:grayscale(.35) contrast(1.02)}

/* 10. brands */
.bt-home .bt-brands{padding-top:clamp(56px,6vw,88px);padding-bottom:clamp(56px,6vw,88px);border-top:1px solid var(--line)}
.bt-home .bt-brands-h{text-align:center;margin-bottom:clamp(30px,3.4vw,48px)}
.bt-home .bt-brands-h .bt-kicker{justify-content:center;margin-bottom:16px}
.bt-home .bt-brands-h .bt-kicker::after{content:"";width:40px;height:1px;background:currentColor}
.bt-home .bt-brands-h p{font-family:var(--serif);font-weight:500;font-size:clamp(24px,2.4vw,34px);line-height:1.2}
.bt-home .bt-logos{display:flex;flex-wrap:wrap;justify-content:center;padding:0 1px 1px 0}
.bt-home .bt-logos li{flex:0 0 16.666%;display:flex;align-items:center;justify-content:center;height:clamp(104px,10vw,148px);padding:18px clamp(14px,2vw,34px);background:#fff;border:1px solid var(--line);margin:0 -1px -1px 0}
.bt-home .bt-logos img{max-width:100%;max-height:62px;width:auto;height:auto;object-fit:contain;filter:grayscale(1) contrast(1.05);opacity:.78;transition:filter .6s var(--ease),opacity .6s var(--ease),transform .6s var(--ease)}
.bt-home .bt-logos li:hover img{filter:none;opacity:1;transform:scale(1.06)}
.bt-home .bt-logos .bt-logos-more{flex-direction:column;gap:6px;text-align:center;background:var(--cream)}
.bt-home .bt-logos-more b{font-family:var(--serif);font-weight:500;font-style:normal;font-size:clamp(17px,1.5vw,21px);line-height:1.15;color:var(--navy)}
.bt-home .bt-logos-more small{font-size:10.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--ink);opacity:.7}

/* 11. faq */
.bt-home .bt-faq{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(32px,6vw,104px);align-items:start}
.bt-home .bt-faq .bt-h2{margin-bottom:22px}
.bt-home .bt-faq-list{border-top:1px solid var(--line)}
.bt-home .bt-faq details{border-bottom:1px solid var(--line)}
.bt-home .bt-faq summary{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:24px 0;cursor:pointer;list-style:none;font-family:var(--serif);font-weight:500;font-size:clamp(21px,1.9vw,27px);line-height:1.25;transition:color .4s var(--ease)}
.bt-home .bt-faq summary::-webkit-details-marker{display:none}
.bt-home .bt-faq summary:hover{color:var(--navy)}
.bt-home .bt-faq summary svg{width:20px;height:20px;color:var(--navy);transition:transform .6s var(--ease)}
.bt-home .bt-faq details[open] summary svg{transform:rotate(45deg)}
.bt-home .bt-faq-a{padding:0 44px 28px 0;color:var(--body);max-width:68ch}
.bt-home .bt-faq-a a{color:var(--navy);border-bottom:1px solid var(--line)}
.bt-home .bt-faq-a a:hover{border-color:var(--navy)}

/* 12. closing band */
.bt-home .bt-close{position:relative;overflow:hidden;text-align:center;padding-top:clamp(110px,13vw,190px);padding-bottom:clamp(110px,13vw,190px)}
.bt-home .bt-close-bg{position:absolute;inset:0;width:100%;height:100%;max-width:none;object-fit:cover}
.bt-home .bt-close::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(180deg,rgba(17,18,19,.56) 0%,rgba(17,18,19,.8) 100%)}
.bt-home .bt-close-in{position:relative;z-index:2}
.bt-home .bt-close .bt-kicker{justify-content:center}
.bt-home .bt-close .bt-kicker::after{content:"";width:40px;height:1px;background:currentColor}
.bt-home .bt-close h2{font-family:var(--serif);font-weight:500;font-size:clamp(44px,6.8vw,104px);line-height:1;letter-spacing:-.018em;color:#fff;margin:0 0 26px}
.bt-home .bt-close h2 em{font-style:normal;color:var(--sand)}
.bt-home .bt-close p.bt-intro{margin:0 auto 40px;color:rgba(255,255,255,.9);font-weight:300}
.bt-home .bt-close .bt-cta-row{justify-content:center}

/* responsive */
/* ---- shop by category ---- */
.bt-home .bt-catgrid{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:clamp(12px,1.3vw,20px);perspective:2400px}
.bt-home .bt-cat-r{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));grid-auto-rows:clamp(236px,21.5vw,330px);gap:clamp(12px,1.3vw,20px);perspective:2000px;min-width:0}
